        return {"repository": f"{owner}/{repo}", "samples": len(rows),
                "from": oldest["captured_at"], "to": newest["captured_at"],
                "latest": {key: newest[key] for key in ("stars", "forks", "open_issues")},
                "change": {key: newest[key] - oldest[key]
